'use client';
import React, { useRef, useState } from 'react';

import { Categories } from 'emoji-picker-react/primitives';
import * as Picker from 'emoji-picker-react/primitives';


// In context: a community forum reply. The community's own custom
// emojis come first in their own group (customEmojis), then the standard
// set. Badges are inline SVG data URIs — no network.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ElementType;
  className?: string;
};

function badge(label: string, background: string) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64"><rect width="64" height="64" rx="16" fill="${background}"/><text x="32" y="40" font-family="Arial, sans-serif" font-size="${label.length > 3 ? 15 : 20}" font-weight="700" fill="#fff" text-anchor="middle">${label}</text></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

const community = [
  ['lgtm', 'LGTM', '#16a34a', ['looks good to me']],
  ['ship', 'SHIP', '#2563eb', ['ship it']],
  ['wip', 'WIP', '#d97706', ['work in progress']],
  ['plus1', '+1', '#7c3aed', ['plus one', 'agree']],
  ['nice', 'NICE', '#db2777', ['nice']],
  ['ack', 'ACK', '#0891b2', ['acknowledged']],
].map(([id, label, color, names]) => ({
  id: id as string,
  names: names as string[],
  imgUrl: badge(label as string, color as string),
  group: 'community',
}));

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  const [reply, setReply] = useState('Huge release, congrats team');
  const input = useRef<HTMLTextAreaElement>(null);
  return (
    <div className="forum-thread">
      <div className="forum-post">
        <span className="forum-tag">Release notes</span>
        <h2>v3.2 is out — faster builds and a new plugin API</h2>
        <p className="forum-byline">posted by @kai · 41 replies</p>
      </div>
      <div className="forum-reply">
        <span className="forum-reply-label">Your reply</span>
        <textarea ref={input} className="forum-editor" aria-label="Reply" rows={1}
          value={reply} onChange={(event) => setReply(event.target.value)} />
        <RootComponent
          className={className}
          customEmojis={community}
          onEmojiClick={(emoji: Picker.EmojiClickData) => {
            const start = input.current?.selectionStart ?? reply.length;
            const end = input.current?.selectionEnd ?? start;
            const insertion = emoji.isCustom ? `:${emoji.unified}:` : emoji.emoji;
            setReply(reply.slice(0, start) + insertion + reply.slice(end));
            requestAnimationFrame(() => {
              input.current?.focus(); input.current?.setSelectionRange(start + insertion.length, start + insertion.length);
            });
          }}
          categories={[
            { category: Categories.CUSTOM, group: 'community', name: 'Community' },
            Categories.SUGGESTED,
            Categories.SMILEYS_PEOPLE,
            Categories.ANIMALS_NATURE,
            Categories.FOOD_DRINK,
            Categories.ACTIVITIES,
            Categories.OBJECTS,
            Categories.SYMBOLS,
          ]}
          searchPlaceholder="Search community and standard emoji"
          autoFocusSearch={false}
        >
          <Picker.Search />
          <Picker.CategoryNav />
          <Picker.Viewport>
            <Picker.List />
            <Picker.Empty />
          </Picker.Viewport>
        </RootComponent>
      </div>
    </div>
  );
}

/* The host app around the picker (shared by every stack variant). */
.forum-thread {
  line-height: 1.4;
  width: 540px;
  padding: 20px;
  border-radius: 14px;
  background: #f4f4f5;
  color: #18181b;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.forum-post {
  padding: 16px 18px;
  border: 1px solid #e4e4e7;
  border-radius: 12px;
  background: #ffffff;
}
.forum-post h2 {
  margin: 8px 0 4px;
  font-size: 17px;
}
.forum-tag {
  padding: 2px 8px;
  border-radius: 999px;
  background: #dcfce7;
  color: #166534;
  font-size: 12px;
  font-weight: 600;
}
.forum-byline {
  margin: 0;
  color: #52525b;
  font-size: 13px;
}
.forum-reply {
  margin-top: 12px;
  padding: 14px 16px 16px;
  border: 1px solid #e4e4e7;
  border-radius: 12px;
  background: #ffffff;
}
.forum-reply-label {
  color: #3f3f46;
  font-size: 13px;
  font-weight: 600;
}
.forum-editor {
  display: block;
  box-sizing: border-box;
  width: 100%;
  resize: none;
  color: inherit;
  font: inherit;
  margin: 8px 0 10px;
  padding: 10px 12px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  font-size: 14px;
}

/* Community custom emojis — an inline reply-box picker; the community's
   badge emojis render as rounded squares like the standard set. */
.forum-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #52525b;
  --epr-highlight-color: #16a34a;
  --epr-hover-bg-color: #f0fdf4;
  --epr-focus-bg-color: #dcfce7;
  --epr-search-input-bg-color: #fafafa;
  --epr-search-input-bg-color-active: #ffffff;
  --epr-search-border-color: #e4e4e7;
  --epr-search-border-color-active: #16a34a;
  --epr-search-input-height: 34px;
  --epr-search-input-border-radius: 8px;
  --epr-search-input-text-color: #18181b;
  --epr-search-input-placeholder-color: #71717a;
  --epr-category-label-bg-color: #fffffff2;
  --epr-category-label-text-color: #52525b;
  --epr-category-label-height: 28px;
  --epr-category-icon-active-color: #15803d;
  --epr-category-icon-inactive-color: #71717a;
  --epr-category-navigation-button-size: 20px;
  --epr-skin-tone-picker-menu-color: #ffffff;
  --epr-emoji-size: 28px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 8px;
  height: 300px;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  background: #ffffff;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.forum-picker [data-epr-part='search'] > * {
  padding: 10px 10px 4px;
}
.forum-picker [data-epr-part='category-nav'] > * {
  padding: 6px 10px;
}
.forum-picker [data-epr-part='category-tab'][aria-selected='true'] {
  border-radius: 6px;
  background-color: #dcfce7;
}
.forum-picker [data-epr-part='category-label'] {
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
}
.forum-picker [data-epr-part='emoji'] {
  border-radius: 8px;
}

